import { NgModule } from '@angular/core';
import { LocationStrategy, NgOptimizedImage, PathLocationStrategy } from '@angular/common';
import { Title } from '@angular/platform-browser';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { TranslateModule, TranslateLoader } from '@ngx-translate/core';
import { Icd10v3Component } from './views/who/icd10v3/icd10v3.component';

import {
    PERFECT_SCROLLBAR_CONFIG,
    PerfectScrollbarConfigInterface,
    PerfectScrollbarModule,
} from 'ngx-perfect-scrollbar';

// Import routing module
import { AppRoutingModule } from './app-routing.module';

// Import app component
import { AppComponent } from './app.component';

// Import containers
import {
    DefaultFooterComponent,
    DefaultHeaderComponent,
    DefaultLayoutComponent,
} from './containers';

import {
    BreadcrumbModule,
    GridModule,
    HeaderModule,
    SidebarModule,
} from '@coreui/angular';

import { IconModule, IconSetService } from '@coreui/icons-angular';
import { HttpClient, HttpClientModule } from '@angular/common/http';
import { MyLinkDirective } from '../shared/directive/my-link.directive';
import { TranslateHttpLoader } from '@ngx-translate/http-loader';
import { ToastrModule } from 'ngx-toastr';
import { LanguageComponent } from './views/who/language/language.component';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms'; // Import FormsModule
import { MaintenancePopupComponent } from '../components/maintenance-popup/maintenance-popup.component';

export function createTranslateLoader(http: HttpClient) {
    return new TranslateHttpLoader(http, './assets/i18n/', '.json');
}

const DEFAULT_PERFECT_SCROLLBAR_CONFIG: PerfectScrollbarConfigInterface = {
    suppressScrollX: true,
};

export function HttpLoaderFactory(http: HttpClient) {
    return new TranslateHttpLoader(http);
}

const APP_CONTAINERS = [
    DefaultFooterComponent,
    DefaultHeaderComponent,
    DefaultLayoutComponent,
    MyLinkDirective,
];

@NgModule({
    declarations: [
        AppComponent,
        ...APP_CONTAINERS,
        LanguageComponent,
        Icd10v3Component, // Thêm Icd10v3Component
        MaintenancePopupComponent,
    ],
    imports: [
        BrowserAnimationsModule,
        BreadcrumbModule,
        GridModule,
        HeaderModule,
        IconModule,
        RouterModule,
        PerfectScrollbarModule,
        SidebarModule,
        HttpClientModule,
        AppRoutingModule,
        TranslateModule.forRoot({
            loader: {
                provide: TranslateLoader,
                useFactory: createTranslateLoader,
                deps: [HttpClient],
            },
        }),
        ToastrModule.forRoot({
            timeOut: 2000,
            positionClass: 'toast-top-right',
            preventDuplicates: true,
        }),
        NgOptimizedImage,
        FormsModule, // Thêm FormsModule
    ],
    providers: [
        {
            provide: LocationStrategy,
            useClass: PathLocationStrategy,
        },
        {
            provide: PERFECT_SCROLLBAR_CONFIG,
            useValue: DEFAULT_PERFECT_SCROLLBAR_CONFIG,
        },
        IconSetService,
        Title,
    ],
    bootstrap: [AppComponent],
})
export class AppModule {}
